// Units shown by default in the United States when they differ from the base unit.
const US_UNITS = { heightCm: { unit: "in", f: 1 / 2.54, dp: 1 } };

// Decimal places shown for U.S. units, matching how labs usually report them.
const US_DP = { creatinine: 2, uacr: 1, upcr: 0, ldl: 0, vitD: 1, b12: 0, troponin: 1, lysoGb3: 2, gb3: 2, ivs: 1, lvmi: 0, pain: 1, fatigue: 1, heightCm: 1,
  ...Object.fromEntries(METRICS_EXTRA.map((m) => [m.id, m.dp ?? 2])) };
const roundTo = (v, dp) => { const k = 10 ** dp; return Math.round(v * k) / k; };
// Every unit a result can be typed in: the base unit first, then the others (no repeats).
function unitOptions(id) {
  const m = metricById(id);
  if (!m || !m.unit || m.kind) return [];
  const base = { unit: m.unit, f: 1, a: 0, dp: US_DP[id] ?? 2 };
  const all = [base, US_UNITS[id], EU_UNITS[id], ...(ALT_UNITS[id] || [])].filter(Boolean);
  return all.filter((o, i) => all.findIndex((x) => x.unit === o.unit) === i);
}
function makeUnits(region) {
  // The unit charts and tables use for this region. null means the base unit.
  const spec = (id) => (region === "eu" ? EU_UNITS[id] : US_UNITS[id]) || null;
  const conv = (o, v) => roundTo(Number(v) * o.f + (o.a || 0), o.dp ?? 2);
  const back = (o, v) => roundTo((Number(v) - (o.a || 0)) / o.f, 4);
  return {
    region,
    unit: (m) => (spec(m.id) ? spec(m.id).unit : m.unit),
    ref: (m) => {
      const sp = spec(m.id);
      if (!sp) return m.ref;
      if (sp.ref || !m.ref) return sp.ref;
      const one = (r) => { const v = conv(sp, r.value); return { value: v, label: `${v} ${sp.unit}` }; };
      return Array.isArray(m.ref) ? m.ref.map(one) : one(m.ref);
    },
    show: (id, v) => (spec(id) ? conv(spec(id), v) : roundTo(Number(v), US_DP[id] ?? 2)),
    store: (id, v) => (spec(id) ? back(spec(id), v) : Number(v)),
    // A value typed in any listed unit, converted to the saved (base) unit.
    storeFrom: (id, v, unit) => {
      const o = unitOptions(id).find((x) => x.unit === unit) || spec(id);
      return o ? back(o, v) : Number(v);
    },
    // A value in the region's unit, converted from one typed in another unit (for a preview).
    convert: (id, v, unit) => {
      const o = unitOptions(id).find((x) => x.unit === unit);
      const saved = o ? back(o, v) : Number(v);
      return spec(id) ? conv(spec(id), saved) : roundTo(saved, US_DP[id] ?? 2);
    },
  };
}
// The United States and its territories use U.S. units; every other country uses metric and SI units.
const US_LIKE = new Set("US PR GU VI AS MP UM".split(" "));
// First guess at the region: a ?region=eu or ?region=us link, then the browser's language setting.
function guessRegion() {
  try {
    const q = new URLSearchParams(window.location.search).get("region");
    if (q === "eu" || q === "us") return q;
    for (const lang of navigator.languages || [navigator.language]) {
      const country = ((String(lang).match(/[-_]([A-Za-z]{2})(?![A-Za-z])/) || [])[1] || "").toUpperCase();
      if (country) return US_LIKE.has(country) ? "us" : "eu";
    }
  } catch (e) { /* fall through */ }
  return "us";
}

