// ---------- Health record connection (SMART on FHIR, for Epic MyChart) ----------
// The patient signs in on their health system's own MyChart page. The app gets read-only access,
// downloads their lab results straight to this device, and never stores the access token.
const EPIC = {
  // Non-production client ID from fhir.epic.com while testing, production client ID when live.
  // Empty means the connection isn't switched on yet: patients can read the steps but can't sign in.
  clientId: "54aba82f-304d-4455-b040-56bc0fc48512", // non-production (Epic sandbox), registered Sept 25, 2026
  scope: "launch/patient openid fhirUser patient/Patient.read patient/Observation.read",
};
// Health systems patients can choose. Add production systems from Epic's published list of patient-access
// endpoints. build.mjs allows the page to contact each fhirBase listed here.
const HEALTH_SYSTEMS = [
  {
    id: "epic-sandbox",
    name: "Epic test system",
    note: "For testing with Epic's sample patients",
    fhirBase: "https://fhir.epic.com/interconnect-fhir-oauth/api/FHIR/R4/",
  },
];
const CONNECT_KEY = "fabry-tracker-connect";
const DEV_CLIENT_KEY = "fabry-tracker-dev-client-id"; // lets a developer test before the client ID is built in
const epicClientId = () => {
  if (EPIC.clientId) return EPIC.clientId;
  try { return window.localStorage.getItem(DEV_CLIENT_KEY) || ""; } catch (e) { return ""; }
};

// Which lab results go on which chart. Most are matched by LOINC code; the Fabry-specific tests often have
// no standard code, so they are matched by name. Values are converted to the units the app saves in.
const normUnit = (u) => (u || "").toLowerCase().replace(/\s/g, "").replace(/[µμ]/g, "u");
const LAB_MAP = [
  { metric: "lysoGb3", loinc: [], name: /lyso[\s-]?(gb3|gl-?3)|globotriaosylsphingosine/i,
    convert: (v, u) => (["nmol/l", "nm", ""].includes(normUnit(u)) ? v : null) },
  { metric: "gb3", loinc: [], name: /globotriaosylceramide|\b(gb3|gl-?3)\b/i,
    convert: (v, u) => (["ug/ml", "mg/l"].includes(normUnit(u)) ? v : null) },
  { metric: "creatinine", loinc: ["2160-0", "38483-4", "14682-9"],
    convert: (v, u) => { const n = normUnit(u); return n === "mg/dl" ? v : n === "umol/l" ? v / 88.4 : null; } },
  { metric: "uacr", loinc: ["9318-7", "14959-1"],
    convert: (v, u) => { const n = normUnit(u); if (/^(mg\/g|ug\/mg)/.test(n)) return v; if (/^mg\/mmol/.test(n)) return v * 8.84; return null; } },
  { metric: "upcr", loinc: ["2890-2"],
    convert: (v, u) => { const n = normUnit(u); if (/^mg\/g/.test(n)) return v; if (/^(mg\/mg|g\/g)/.test(n)) return v * 1000; if (/^mg\/mmol/.test(n)) return v * 8.84; return null; } },
  { metric: "troponin", loinc: ["89579-7", "67151-1", "6598-7", "10839-9"],
    convert: (v, u) => { const n = normUnit(u); if (n === "ng/l" || n === "pg/ml") return v; if (n === "ng/ml" || n === "ug/l") return v * 1000; return null; } },
  { metric: "vitD", loinc: ["62292-8", "1989-3"],
    convert: (v, u) => { const n = normUnit(u); if (n === "ng/ml" || n === "ug/l") return v; if (n === "nmol/l") return v / 2.496; return null; } },
  { metric: "b12", loinc: ["2132-9"],
    convert: (v, u) => { const n = normUnit(u); if (n === "pg/ml" || n === "ng/l") return v; if (n === "pmol/l") return v / 0.7378; return null; } },
  { metric: "ldl", loinc: ["13457-7", "18262-6", "2089-1"],
    convert: (v, u) => { const n = normUnit(u); if (n === "mg/dl") return v; if (n === "mmol/l") return v * 38.67; return null; } },
  // Tests for the other conditions. Codes checked on loinc.org.
  ...[
    ["phos", ["2777-1", "14879-1"], { "mg/dl": 1, "mmol/l": 1 / 0.3229 }],
    ["alp", ["6768-6"], { "u/l": 1, "iu/l": 1 }],
    ["pth", ["2731-8", "14866-8"], { "pg/ml": 1, "ng/l": 1, "pmol/l": 1 / 0.106 }],
    ["calcium", ["17861-6", "2000-8"], { "mg/dl": 1, "mmol/l": 1 / 0.2495 }],
    ["potassium", ["2823-3"], { "mmol/l": 1, "meq/l": 1 }],
    ["bicarb", ["2028-9", "1963-8"], { "mmol/l": 1, "meq/l": 1 }],
    ["mg", ["19123-9"], { "mg/dl": 1, "mmol/l": 1 / 0.4114 }],
    ["urate", ["3084-1"], { "mg/dl": 1, "umol/l": 1 / 59.48 }],
    ["tg", ["2571-8"], { "mg/dl": 1, "mmol/l": 1 / 0.01129 }],
    ["alt", ["1742-6", "1743-4"], { "u/l": 1, "iu/l": 1 }],
    ["ast", ["1920-8", "30239-8"], { "u/l": 1, "iu/l": 1 }],
    ["tsh", ["3016-3", "11580-8"], { "miu/l": 1, "m[iu]/l": 1, "uiu/ml": 1, "u[iu]/ml": 1 }],
    ["hgb", ["718-7"], { "g/dl": 1, "g/l": 0.1 }],
    ["plt", ["777-3", "26515-7"], { "10*3/ul": 1, "10^3/ul": 1, "k/ul": 1, "10*9/l": 1, "10^9/l": 1, "x10e3/ul": 1 }],
    ["ck", ["2157-6"], { "u/l": 1, "iu/l": 1 }],
    ["uox", ["2701-1", "14862-7"], { "mg/(24.h)": 1, "mg/24h": 1, "mg/d": 1, "umol/(24.h)": 0.09003, "umol/24h": 0.09003, "mmol/(24.h)": 90.03, "mmol/24h": 90.03 }],
    ["pox", ["15085-4", "2699-7"], { "umol/l": 1, "mg/l": 11.107 }],
    ["chito", ["38355-4"], { "nmol/h/ml": 1, "u/l": 60, "nmol/min/ml": 60 }],
    ["hex4", ["53868-6"], { "mmol/mol{creat}": 1, "mmol/mol": 1 }],
    ["ugag", ["32799-9"], { "mg/mmol{creat}": 1, "mg/mmol": 1, "mg/g{creat}": 1 / 8.84, "mg/g": 1 / 8.84 }],
    ["wbcCystine", ["33872-3"], { "nmol{1/2cys}/mg{protein}": 1, "nmol/mg": 1, "nmol/mg{protein}": 1 }],
    ["freeT4", ["3024-7"], { "ng/dl": 1, "pmol/l": 1 / 12.87 }],
    ["carnitine", ["14286-9"], { "umol/l": 1, "nmol/ml": 1 }],
    ["copper", ["5631-7"], { "ug/dl": 1, "mcg/dl": 1, "umol/l": 1 / 0.1574 }],
  ].map(([metric, loinc, units]) => ({
    metric, loinc,
    convert: (v, u) => { const f = units[normUnit(u)]; return f === undefined ? null : v * f; },
  })),
  { metric: "hba1c", loinc: ["4548-4", "17856-6", "59261-8"],
    convert: (v, u) => { const n = normUnit(u); if (n === "%") return v; if (n === "mmol/mol") return v / 10.929 + 2.15; return null; } },
  { metric: "lysoGb1", loinc: ["92750-9"], name: /lyso[\s-]?gb1|glucosylsphingosine|glucopsychosine/i,
    convert: (v, u) => { const n = normUnit(u); if (n === "ng/ml") return v; if (n === "nmol/l") return v * 0.4616; if (n === "nmol/ml") return v * 461.6; return null; } },
];
const FINAL_STATUS = new Set(["final", "amended", "corrected"]);

function labRule(obs) {
  const codings = (obs.code && obs.code.coding) || [];
  const codes = codings.filter((c) => !c.system || /loinc/i.test(c.system)).map((c) => c.code);
  const name = [obs.code && obs.code.text, ...codings.map((c) => c.display)].filter(Boolean).join(" ");
  return LAB_MAP.find((r) => r.loinc.some((c) => codes.includes(c))) || LAB_MAP.find((r) => r.name && r.name.test(name)) || null;
}

// Returns { entries: [{ fhirId, date, metric, value }], skipped: [{ name, reason }] }
function mapObservations(observations) {
  const entries = [];
  const skipped = [];
  observations.forEach((obs) => {
    if (!obs || obs.resourceType !== "Observation") return;
    const rule = labRule(obs);
    if (!rule) return; // a test this app doesn't chart
    const name = (obs.code && (obs.code.text || ((obs.code.coding || [])[0] || {}).display)) || rule.metric;
    if (!FINAL_STATUS.has(obs.status)) { skipped.push({ name, reason: "not final yet" }); return; }
    const q = obs.valueQuantity;
    if (!q || typeof q.value !== "number" || !isFinite(q.value)) { skipped.push({ name, reason: "no number" }); return; }
    const date = String(obs.effectiveDateTime || (obs.effectivePeriod && obs.effectivePeriod.start) || obs.issued || "").slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) { skipped.push({ name, reason: "no date" }); return; }
    const value = rule.convert(q.value, q.unit || q.code);
    if (value === null || !isFinite(value)) { skipped.push({ name, reason: `unit ${q.unit || q.code || "missing"}` }); return; }
    entries.push({ fhirId: String(obs.id || `${rule.metric}-${date}-${value}`), date, metric: rule.metric, value: roundTo(value, 4) });
  });
  return { entries, skipped };
}

const b64url = (bytes) => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const randomString = (n) => { const a = new Uint8Array(n); crypto.getRandomValues(a); return b64url(a).slice(0, n); };
const withSlash = (u) => (u.endsWith("/") ? u : `${u}/`);
// The app's own address, exactly as registered with Epic as the redirect URI.
const appAddress = () => `${window.location.origin}${window.location.pathname.replace(/index\.html$/, "")}`;

async function fetchJSON(url, options = {}, what = "your health system") {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 20000);
  let res;
  try {
    res = await fetch(url, { ...options, signal: ctrl.signal });
  } catch (e) {
    throw new Error(e.name === "AbortError" ? `${what} took too long to answer` : `${what} couldn't be reached`);
  } finally {
    clearTimeout(timer);
  }
  if (!res.ok) throw new Error(`${what} answered with an error (${res.status})`);
  return res.json();
}

// Step 1 of sign-in: send the patient to their health system's MyChart login page.
async function startSignIn(system) {
  const cfg = await fetchJSON(`${withSlash(system.fhirBase)}.well-known/smart-configuration`, {}, system.name);
  if (!isWebLink(cfg.authorization_endpoint) || !isWebLink(cfg.token_endpoint)) {
    throw new Error(`${system.name}'s sign-in details couldn't be read`);
  }
  const verifier = randomString(64);
  const challenge = b64url(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier)));
  const state = randomString(32);
  sessionStorage.setItem(CONNECT_KEY, JSON.stringify({
    state, verifier, systemId: system.id, tokenEndpoint: cfg.token_endpoint, redirectUri: appAddress(),
  }));
  const q = new URLSearchParams({
    response_type: "code", client_id: epicClientId(), redirect_uri: appAddress(), scope: EPIC.scope, state,
    aud: system.fhirBase, code_challenge: challenge, code_challenge_method: "S256",
  });
  window.location.assign(`${cfg.authorization_endpoint}?${q.toString()}`);
}

const isReturnFromSignIn = () => {
  if (typeof window === "undefined") return false;
  const q = new URLSearchParams(window.location.search);
  return q.has("state") && (q.has("code") || q.has("error"));
};

// Step 2 of sign-in: back from MyChart. Swap the one-time code for an access token, download the
// patient's details and lab results, and hand back what was found. Nothing is saved here.
async function finishSignIn() {
  const q = new URLSearchParams(window.location.search);
  window.history.replaceState({}, "", window.location.pathname); // remove the one-time code from the address bar
  let saved = null;
  try { saved = JSON.parse(sessionStorage.getItem(CONNECT_KEY)); } catch (e) { saved = null; }
  sessionStorage.removeItem(CONNECT_KEY);
  if (q.get("error")) {
    throw new Error(q.get("error") === "access_denied"
      ? "You chose not to share your results, so nothing was downloaded."
      : `Your health system stopped the sign-in: ${q.get("error_description") || q.get("error")}.`);
  }
  if (!saved || saved.state !== q.get("state")) throw new Error("This sign-in couldn't be verified. Please start again.");
  const system = HEALTH_SYSTEMS.find((s) => s.id === saved.systemId);
  if (!system) throw new Error("That health system is no longer in the list. Please start again.");

  const token = await fetchJSON(saved.tokenEndpoint, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
    body: new URLSearchParams({
      grant_type: "authorization_code", code: q.get("code") || "", redirect_uri: saved.redirectUri,
      client_id: epicClientId(), code_verifier: saved.verifier,
    }).toString(),
  }, system.name);
  if (!token.access_token || !token.patient) throw new Error(`${system.name} didn't grant access to your record`);

  const base = withSlash(system.fhirBase);
  const origin = new URL(base).origin;
  const get = (url) => fetchJSON(url, { headers: { Authorization: `Bearer ${token.access_token}`, Accept: "application/fhir+json" } }, system.name);
  const patient = await get(`${base}Patient/${encodeURIComponent(token.patient)}`);
  const observations = [];
  let url = `${base}Observation?patient=${encodeURIComponent(token.patient)}&category=laboratory&_count=200`;
  for (let page = 0; url && page < 20; page++) {
    const bundle = await get(url);
    (bundle.entry || []).forEach((e) => { if (e.resource && e.resource.resourceType === "Observation") observations.push(e.resource); });
    const next = (bundle.link || []).find((l) => l.relation === "next");
    // Only follow "next page" links on the same server, so the access token never goes anywhere else.
    url = next && isWebLink(next.url) && new URL(next.url).origin === origin ? next.url : null;
  }
  const name = (patient.name || [])[0] || {};
  const { entries, skipped } = mapObservations(observations);
  return {
    systemName: system.name,
    patientName: name.text || [...(name.given || []), name.family].filter(Boolean).join(" "),
    profile: {
      birthDate: /^\d{4}-\d{2}-\d{2}$/.test(patient.birthDate || "") ? patient.birthDate : "",
      sex: patient.gender === "female" ? "Female" : patient.gender === "male" ? "Male" : "",
    },
    totalLabs: observations.length,
    entries,
    skipped,
  };
}

function Bullets({ items }) {
  return (
    <ul className="text-sm" style={{ color: C.ink }}>
      {items.map((t) => (
        <li key={t.slice(0, 40)} className="flex gap-2 mb-2">
          <span aria-hidden="true" className="rounded-full" style={{ width: 6, height: 6, marginTop: 7, flexShrink: 0, background: C.accent }} />
          <span>{t}</span>
        </li>
      ))}
    </ul>
  );
}

function Spinner() {
  return (
    <span aria-hidden="true" className="inline-block rounded-full fx-spin"
      style={{ width: 28, height: 28, border: `3px solid ${C.line}`, borderTopColor: C.accent }} />
  );
}

function StepList({ items }) {
  return (
    <ol className="mb-4">
      {items.map((t, k) => (
        <li key={k} className="flex gap-3 mb-3 text-base">
          <span aria-hidden="true" className="flex items-center justify-center rounded-full text-sm font-bold"
            style={{ width: 28, height: 28, flexShrink: 0, background: C.accentSoft, color: C.accent }}>{k + 1}</span>
          <span>{t}</span>
        </li>
      ))}
    </ol>
  );
}

// Walks a patient through connecting their MyChart account, one screen at a time.
function ConnectWizard({ connect, setConnect, region, units, profile, personName, metricIds, existingFhirIds, onImport, onClose, onSeeCharts }) {
  const [systemId, setSystemId] = useState(HEALTH_SYSTEMS.length === 1 ? HEALTH_SYSTEMS[0].id : "");
  const [search, setSearch] = useState("");
  const [useProfile, setUseProfile] = useState(true);
  const system = HEALTH_SYSTEMS.find((s) => s.id === systemId);
  const stage = region === "eu" && ["intro", "system", "prepare"].includes(connect.stage) ? "europe" : connect.stage;
  const go = (s) => setConnect({ ...connect, stage: s });
  const clientReady = Boolean(epicClientId());
  const numbered = { intro: 1, system: 2, prepare: 3 };

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape" && !["signing", "working"].includes(stage)) onClose(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [stage]);

  const signIn = async () => {
    go("signing");
    try {
      await startSignIn(system);
    } catch (e) {
      setConnect({ stage: "error", error: `${e.message}. Check your internet connection and try again.` });
    }
  };

  let body;
  if (stage === "europe") {
    body = (
      <>
        <h2 className="text-2xl font-bold mb-2">Available in the United States only</h2>
        <p className="text-base mb-4">
          Connecting a patient portal currently works only with health systems in the United States. You can keep adding
          your results on the Add tab.
        </p>
        <Button onClick={onClose}>Close</Button>
      </>
    );
  } else if (stage === "intro") {
    body = (
      <>
        <h2 className="text-2xl font-bold mb-2">Bring in your lab results</h2>
        <p className="text-base mb-4">
          If your health system uses Epic MyChart, you can copy your lab results into {APP_INFO.name} instead of typing them.
        </p>
        <section className="p-4 mb-4 rounded-lg" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
          <Bullets items={[
            `You sign in on your health system's own MyChart page. ${APP_INFO.name} never sees your password.`,
            `${APP_INFO.name} can only read your results. It can't change anything in your medical record.`,
            "Your results come straight to this device. They aren't sent to the app's developers.",
            "You'll see what was found before anything is added.",
          ]} />
        </section>
        {personName && (
          <p className="text-base mb-4 p-3 rounded-md" style={{ background: C.accentSoft }}>
            Results will be added to <span className="font-bold">{personName} record</span>. Sign in with
            {personName === "your" ? " your own" : " their"} MyChart account, or with proxy access you have to it.
          </p>
        )}
        <p className="text-sm mb-5" style={{ color: C.muted }}>
          Kidney, cholesterol, vitamin and troponin results usually come through. Lyso-Gb3 and heart ultrasound
          measurements often don't, so you may still need to add those on the Add tab.
        </p>
        <Button onClick={() => go("system")}>Get started</Button>
      </>
    );
  } else if (stage === "system") {
    const q = search.trim().toLowerCase();
    const list = HEALTH_SYSTEMS.filter((s) => !q || `${s.name} ${s.note || ""}`.toLowerCase().includes(q));
    body = (
      <>
        <h2 className="text-2xl font-bold mb-2">Choose your health system</h2>
        <p className="text-base mb-3">Pick the health system whose MyChart you use.</p>
        {HEALTH_SYSTEMS.length > 6 && (
          <input className={inputCls + " mb-3"} style={inputStyle} placeholder="Search by name or city" aria-label="Search health systems"
            value={search} onChange={(e) => setSearch(e.target.value)} />
        )}
        <div className="mb-3" role="radiogroup" aria-label="Health systems">
          {list.map((s) => {
            const on = s.id === systemId;
            return (
              <label key={s.id} className="fx-press flex items-start gap-3 p-3 mb-2 rounded-md cursor-pointer focus-within:ring-2"
                style={{ border: `2px solid ${on ? C.accent : C.line}`, background: on ? C.accentSoft : C.surface }}>
                <input type="radio" name="health-system" checked={on} onChange={() => setSystemId(s.id)} className="mt-1"
                  style={{ accentColor: "var(--accent)" }} />
                <span>
                  <span className="block text-base font-bold">{s.name}</span>
                  {s.note && <span className="block text-sm" style={{ color: C.muted }}>{s.note}</span>}
                </span>
              </label>
            );
          })}
          {list.length === 0 && <p className="text-base" style={{ color: C.muted }}>No health systems match that search.</p>}
        </div>
        <p className="text-sm mb-5" style={{ color: C.muted }}>
          Don't see yours? Only the health systems listed here are connected so far. You can still add your results on the Add tab.
        </p>
        <div className="flex gap-2">
          <Button kind="secondary" onClick={() => go("intro")}>Back</Button>
          <Button onClick={() => go("prepare")} disabled={!system}>Next</Button>
        </div>
      </>
    );
  } else if (stage === "prepare") {
    body = (
      <>
        <h2 className="text-2xl font-bold mb-3">Before you sign in</h2>
        <StepList items={[
          "Have your MyChart username and password ready. If you've forgotten them, use MyChart's \"Forgot\" link on the sign-in page.",
          `You'll leave ${APP_INFO.name} for a moment and see ${system ? system.name : "your health system"}'s MyChart sign-in page. Sign in there.`,
          `MyChart will ask whether ${APP_INFO.name} may see your information. Choose Allow.`,
          `You'll come back here automatically to review your results.`,
        ]} />
        {!clientReady && (
          <p className="text-sm mb-4 p-3 rounded-md" role="status" style={{ background: C.subtle, border: `1px solid ${C.line}` }}>
            The connection isn't switched on yet. The app's developers will turn it on once their registration with Epic is
            finished. Until then, you can add your results on the Add tab.
          </p>
        )}
        <div className="flex gap-2">
          <Button kind="secondary" onClick={() => go("system")}>Back</Button>
          <Button onClick={signIn} disabled={!clientReady || !system}>Sign in to MyChart</Button>
        </div>
      </>
    );
  } else if (stage === "signing" || stage === "working") {
    body = (
      <div className="flex flex-col items-center text-center py-10">
        <Spinner />
        <p className="text-lg font-bold mt-4" role="status">
          {stage === "signing" ? "Opening MyChart…" : "Getting your results…"}
        </p>
        <p className="text-sm mt-1" style={{ color: C.muted }}>
          {stage === "signing" ? "You'll see your health system's sign-in page in a moment." : "This usually takes a few seconds."}
        </p>
      </div>
    );
  } else if (stage === "review") {
    const r = connect.result;
    // Only the tests this condition tracks are offered.
    const fresh = r.entries.filter((e) => !existingFhirIds.has(e.fhirId) && (!metricIds || metricIds.has(e.metric)));
    const already = r.entries.filter((e) => existingFhirIds.has(e.fhirId)).length;
    const byMetric = {};
    fresh.forEach((e) => { (byMetric[e.metric] = byMetric[e.metric] || []).push(e); });
    const needProfile = (r.profile.birthDate && r.profile.birthDate !== profile.birthDate) || (r.profile.sex && r.profile.sex !== profile.sex);
    body = (
      <>
        <h2 className="text-2xl font-bold mb-1">Here's what we found</h2>
        <p className="text-base mb-4" style={{ color: C.muted }}>
          From {r.systemName}{r.patientName ? ` for ${r.patientName}` : ""}. {r.totalLabs} lab results were checked.
        </p>
        {fresh.length > 0 ? (
          <ul className="mb-3 rounded-lg" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
            {METRICS.filter((m) => byMetric[m.id]).map((m, k) => {
              const list = byMetric[m.id].sort((a, b) => a.date.localeCompare(b.date));
              const latest = list[list.length - 1];
              return (
                <li key={m.id} className="flex justify-between gap-3 px-4 py-3 text-base" style={{ borderTop: k ? `1px solid ${C.line}` : "none" }}>
                  <span>
                    <span className="font-bold">{m.label}</span>
                    <span className="block text-sm" style={{ color: C.muted }}>
                      Latest {units.show(m.id, latest.value)} {units.unit(m)} on {fmtDate(toT(latest.date))}
                    </span>
                  </span>
                  <span className="font-bold" style={{ color: C.accent }}>{list.length}</span>
                </li>
              );
            })}
          </ul>
        ) : (
          <p className="text-base mb-3 p-3 rounded-md" style={{ background: C.subtle }}>
            {`No new results for ${APP_INFO.name}'s charts were found.`}
          </p>
        )}
        {already > 0 && <p className="text-sm mb-1" style={{ color: C.muted }}>{already} results were already added before and will be skipped.</p>}
        {r.skipped.length > 0 && (
          <p className="text-sm mb-1" style={{ color: C.muted }}>
            {r.skipped.length} results were left out because they weren't final yet or used a unit the app can't convert.
          </p>
        )}
        {needProfile && (
          <label className="flex items-start gap-2 mt-3 text-sm">
            <input type="checkbox" checked={useProfile} onChange={(e) => setUseProfile(e.target.checked)} className="mt-1"
              style={{ accentColor: "var(--accent)" }} />
            <span>
              Update my profile with the birth date{r.profile.sex ? ` and sex (${r.profile.sex})` : ""} from my record. Check
              that the sex matches the one you want used to calculate kidney function.
            </span>
          </label>
        )}
        <div className="flex flex-wrap gap-2 mt-5">
          {fresh.length > 0 || (needProfile && useProfile) ? (
            <>
              <Button onClick={() => {
                const n = onImport(fresh, needProfile && useProfile ? r.profile : null, r.systemName);
                setConnect({ stage: "done", added: n, systemName: r.systemName });
              }}>
                {fresh.length ? `Add ${fresh.length} results` : "Update my profile"}
              </Button>
              <Button kind="secondary" onClick={onClose}>Don't add</Button>
            </>
          ) : (
            <Button onClick={onClose}>Close</Button>
          )}
        </div>
      </>
    );
  } else if (stage === "done") {
    body = (
      <>
        <h2 className="text-2xl font-bold mb-2">All set</h2>
        <p className="text-base mb-4">
          {connect.added ? `${connect.added} results from ${connect.systemName} are now on your charts.` : "Your profile was updated."}
        </p>
        <section className="p-4 mb-4 rounded-lg" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
          <h3 className="text-base font-bold mb-1">Getting new results later</h3>
          <p className="text-sm mb-3">
            After your next lab tests, open Settings, choose Connect your health record, and sign in again. Results you've
            already added won't be added twice.
          </p>
          <h3 className="text-base font-bold mb-1">Stopping sharing</h3>
          <p className="text-sm">
            {APP_INFO.name} doesn't keep ongoing access: each connection ends when you finish. To review apps you've allowed,
            look in MyChart's settings, often under Linked Apps and Devices.
          </p>
        </section>
        <Button onClick={onSeeCharts}>See my charts</Button>
      </>
    );
  } else {
    body = (
      <>
        <h2 className="text-2xl font-bold mb-2">The connection didn't work</h2>
        <p className="text-base mb-5" role="alert">{connect.error}</p>
        <div className="flex gap-2">
          <Button onClick={() => setConnect({ stage: "system" })}>Try again</Button>
          <Button kind="secondary" onClick={onClose}>Close</Button>
        </div>
      </>
    );
  }

  return (
    <div role="dialog" aria-modal="true" aria-label="Connect your health record" className="fixed inset-0 z-50 overflow-y-auto"
      style={{ background: C.bg, color: C.ink, paddingTop: "env(safe-area-inset-top)", paddingBottom: "env(safe-area-inset-bottom)" }}>
      <div className="sticky top-0 z-10" style={{ background: C.bg, borderBottom: `1px solid ${C.line}` }}>
        <div className="max-w-xl mx-auto px-4 flex items-center justify-between" style={{ height: 52 }}>
          <span className="text-base font-bold" style={{ color: C.accent }}>Connect your health record</span>
          {!["signing", "working"].includes(stage) && (
            <button onClick={onClose} aria-label="Close" className="fx-press flex items-center justify-center rounded-md text-2xl leading-none focus:outline-none focus:ring-2"
              style={{ width: 44, height: 44, color: C.muted, marginRight: -10 }}>×</button>
          )}
        </div>
      </div>
      <div key={stage} className="fx-fade max-w-xl mx-auto px-4 py-5">
        {numbered[stage] && (
          <p className="text-sm font-bold mb-1" style={{ color: C.muted }}>Step {numbered[stage]} of 3</p>
        )}
        {body}
      </div>
    </div>
  );
}

// ---------- Guided tour ----------
