// Highlights one part of the real screen at a time with a short explanation.
function Tour({ onClose, onSample, hasEntries, onTab, quickLog = true }) {
  // Conditions without a quick log (like Alport syndrome) skip that step.
  const TOUR_STEPS = ALL_TOUR_STEPS.filter((st) => quickLog || st.target !== "quicklog");
  const [i, setI] = useState(0);
  const [rect, setRect] = useState(null);
  const [vw, setVw] = useState(() => window.innerWidth);
  const [vh, setVh] = useState(() => window.innerHeight);
  const nextRef = useRef(null);
  const cardRef = useRef(null);
  const [cardH, setCardH] = useState(240);
  const step = TOUR_STEPS[i];
  useLayoutEffect(() => {
    if (cardRef.current) setCardH(cardRef.current.getBoundingClientRect().height);
  }, [i, vw]);

  const findTarget = () => {
    for (const name of [step.target, step.fallback]) {
      if (!name) continue;
      const el = document.querySelector(`[data-tour="${name}"]`);
      if (el && el.getBoundingClientRect().height > 0) return el;
    }
    return null;
  };

  useEffect(() => {
    let frame = 0;
    let started = 0;
    // Steps on another page open it first, then highlight once it has drawn.
    if (step.tab) onTab(step.tab);
    const measure = () => {
      setVw(window.innerWidth);
      setVh(window.innerHeight);
      const target = findTarget();
      setRect(target ? target.getBoundingClientRect() : null);
    };
    const begin = () => {
      const el = findTarget();
      if (el && getComputedStyle(el).position !== "fixed" && !el.closest("nav, .sticky")) {
        // Tall parts are lined up with the top of the screen so their start shows; short ones are centered.
        const tall = el.getBoundingClientRect().height > window.innerHeight * 0.45;
        if (tall) {
          const top = el.getBoundingClientRect().top + window.scrollY - 80;
          window.scrollTo({ top, behavior: REDUCED ? "auto" : "smooth" });
        } else {
          el.scrollIntoView({ block: "center", behavior: REDUCED ? "auto" : "smooth" });
        }
      }
      measure();
    };
    started = setTimeout(begin, step.tab ? 60 : 0);
    const t = setTimeout(measure, REDUCED ? 80 : 520);
    const onMove = () => { cancelAnimationFrame(frame); frame = requestAnimationFrame(measure); };
    window.addEventListener("resize", onMove);
    window.addEventListener("scroll", onMove, true);
    if (nextRef.current) nextRef.current.focus({ preventScroll: true });
    return () => {
      clearTimeout(t);
      clearTimeout(started);
      cancelAnimationFrame(frame);
      window.removeEventListener("resize", onMove);
      window.removeEventListener("scroll", onMove, true);
    };
  }, [i]);

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowRight" && i < TOUR_STEPS.length - 1) setI(i + 1);
      if (e.key === "ArrowLeft" && i > 0) setI(i - 1);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [i]);

  const pad = 6;
  const cardW = Math.min(360, vw - 32);
  const spot = rect && {
    left: rect.left - pad, top: rect.top - pad, width: rect.width + pad * 2, height: rect.height + pad * 2,
  };
  // The card goes below the highlight if it fits, else above, else pinned to the bottom of the screen.
  // With nothing highlighted it is centered.
  const margin = 12;
  let cardStyle;
  if (!spot) {
    cardStyle = { left: (vw - cardW) / 2, top: Math.max(margin, (vh - cardH) / 2) };
  } else {
    const left = Math.max(16, Math.min(spot.left + spot.width / 2 - cardW / 2, vw - cardW - 16));
    const spaceBelow = vh - (spot.top + spot.height) - margin * 2;
    const spaceAbove = spot.top - margin * 2;
    if (cardH <= spaceBelow) cardStyle = { left, top: spot.top + spot.height + margin };
    else if (cardH <= spaceAbove) cardStyle = { left, top: spot.top - margin - cardH };
    else cardStyle = { left, bottom: `calc(${margin}px + env(safe-area-inset-bottom))` };
  }

  return (
    <div className="fixed inset-0 z-50" role="dialog" aria-modal="true" aria-labelledby="tour-title" aria-describedby="tour-body">
      {spot ? (
        <div aria-hidden="true" className="fixed rounded-xl pointer-events-none"
          style={{ ...spot, boxShadow: `0 0 0 9999px ${C.scrim}`, outline: `3px solid ${C.accent}`, outlineOffset: 0,
            transition: REDUCED ? "none" : "all 350ms cubic-bezier(.2,.9,.3,1)" }} />
      ) : (
        <div aria-hidden="true" className="fixed inset-0" style={{ background: C.scrim }} />
      )}
      <div key={i} ref={cardRef} className="fx-fade fixed rounded-lg p-4" style={{ ...cardStyle, width: cardW, background: C.surface, color: C.ink,
        boxShadow: `0 8px 30px ${C.shadow}`, border: `1px solid ${C.line}` }}>
        <div className="flex items-center justify-between mb-1">
          <span className="text-xs font-bold" style={{ color: C.muted }}>Step {i + 1} of {TOUR_STEPS.length}</span>
          {!step.last && (
            <button onClick={onClose} className="text-sm underline focus:outline-none focus:ring-2" style={{ color: C.muted }}>
              Skip tour
            </button>
          )}
        </div>
        <h2 id="tour-title" className="text-lg font-bold mb-1">{step.title}</h2>
        {step.lead && <p className="text-base mb-2">{step.lead}</p>}
        {step.motto && <p className="text-base font-bold mb-3" style={{ color: C.accent }}>{step.motto}</p>}
        <p id="tour-body" className="text-base mb-3">{step.body}</p>
        <div className="flex items-center gap-1 mb-3" aria-hidden="true">
          {TOUR_STEPS.map((_, k) => (
            <span key={k} className="rounded-full" style={{ width: k === i ? 16 : 6, height: 6,
              background: k === i ? C.accent : C.line, transition: REDUCED ? "none" : "width 200ms" }} />
          ))}
        </div>
        <div className="flex flex-wrap gap-2">
          {i > 0 && !step.last && <Button kind="secondary" onClick={() => setI(i - 1)}>Back</Button>}
          {step.last ? (
            <>
              {!hasEntries && <Button kind="secondary" onClick={() => { onClose(); onSample(); }}>Explore with sample data</Button>}
              <button ref={nextRef} onClick={onClose}
                className="fx-press px-4 py-2 rounded-md text-base font-bold focus:outline-none focus:ring-2"
                style={{ background: C.accent, color: C.onAccent }}>
                Start tracking
              </button>
            </>
          ) : (
            <button ref={nextRef} onClick={() => setI(i + 1)}
              className="fx-press px-4 py-2 rounded-md text-base font-bold focus:outline-none focus:ring-2"
              style={{ background: C.accent, color: C.onAccent }}>
              {i === 0 ? "Show me around" : "Next"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// Install-to-home-screen support. main.jsx keeps the browser's install prompt on window.
function useInstall() {
  const [prompt, setPrompt] = useState(() => (typeof window !== "undefined" && window.__fabryInstallPrompt) || null);
  useEffect(() => {
    const ready = () => setPrompt(window.__fabryInstallPrompt || null);
    window.addEventListener("fabry-install-ready", ready);
    return () => window.removeEventListener("fabry-install-ready", ready);
  }, []);
  const standalone = typeof window !== "undefined"
    && ((window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) || window.navigator.standalone === true);
  const ios = typeof navigator !== "undefined"
    && (/iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1));
  const install = async () => {
    if (!prompt) return;
    prompt.prompt();
    try { await prompt.userChoice; } catch (e) { /* dismissed */ }
    window.__fabryInstallPrompt = null;
    setPrompt(null);
  };
  return { canPrompt: Boolean(prompt), install, standalone, ios };
}

function InstallSection() {
  const { canPrompt, install, standalone, ios } = useInstall();
  return (
    <section className="mb-5">
      <h3 className="text-base font-bold mb-1">Add to your home screen</h3>
      {standalone ? (
        <p className="text-sm" style={{ color: C.muted }}>{APP_INFO.name} is installed on this device.</p>
      ) : canPrompt ? (
        <>
          <p className="text-sm mb-2" style={{ color: C.muted }}>Open {APP_INFO.name} like any other app, even without internet.</p>
          <Button onClick={install}>Install {APP_INFO.name}</Button>
        </>
      ) : ios ? (
        <p className="text-sm" style={{ color: C.muted }}>
          In Safari, tap the Share button, then Add to Home Screen. Installing also keeps your record safer, because Safari can
          clear data from websites you haven't opened for a while. Your record doesn't move over on its own: export a
          backup here first, then restore it in the installed app.
        </p>
      ) : (
        <p className="text-sm" style={{ color: C.muted }}>
          Open your browser's menu and choose Install app or Add to Home screen.
        </p>
      )}
    </section>
  );
}

// Contact us: messages go by email. The app only opens the patient's own email app.
// Rate the app: 1 to 5 stars and an optional comment, sent anonymously to the developers' Google Form.
const REVIEW_KEY = "fabry-tracker-reviewed";
// Asking for a review: first a week after someone starts using the app, then every 6 weeks.
// The clock restarts after a review is sent or "Not now". "Don't ask again" stops the reminders.
const REVIEW_ASK_KEY = "fabry-tracker-review-ask"; // { first, last, never }
const REVIEW_FIRST_DAYS = 7;
const REVIEW_EVERY_DAYS = 42;
const readAsk = () => { try { return JSON.parse(window.localStorage.getItem(REVIEW_ASK_KEY)) || {}; } catch (e) { return {}; } };
const writeAsk = (a) => { try { window.localStorage.setItem(REVIEW_ASK_KEY, JSON.stringify(a)); } catch (e) { /* not critical */ } };
const daysSince = (iso) => (Date.now() - Date.parse(iso)) / 864e5;
function reviewDue() {
  const a = readAsk();
  if (a.never || !a.first || isNaN(Date.parse(a.first))) return false;
  let reviewed = "";
  try { reviewed = window.localStorage.getItem(REVIEW_KEY) || ""; } catch (e) { /* none */ }
  const last = [a.last, reviewed].filter((d) => d && !isNaN(Date.parse(d))).sort().pop();
  return last ? daysSince(last) >= REVIEW_EVERY_DAYS : daysSince(a.first) >= REVIEW_FIRST_DAYS;
}

function ReviewPrompt({ onReview, onLater, onNever }) {
  const goRef = useRef(null);
  useEffect(() => {
    if (goRef.current) goRef.current.focus();
    const onKey = (e) => { if (e.key === "Escape") onLater(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);
  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-4" style={{ background: C.scrim }} onClick={onLater}>
      <div role="dialog" aria-modal="true" aria-labelledby="ask-title" className="fx-fade w-full max-w-sm rounded-lg p-5 text-center"
        style={{ background: C.surface, color: C.ink, marginBottom: "env(safe-area-inset-bottom)", boxShadow: `0 8px 30px ${C.shadow}` }}
        onClick={(e) => e.stopPropagation()}>
        <div className="flex justify-center gap-1 mb-2" aria-hidden="true">
          {[1, 2, 3, 4, 5].map((n) => <StarIcon key={n} filled />)}
        </div>
        <h2 id="ask-title" className="text-xl font-bold mb-2">Tell us what you think of the {APP_INFO.name}.</h2>
        <p className="text-base mb-4" style={{ color: C.muted }}>It takes less than a minute, and it helps us make the app better.</p>
        <div className="flex flex-col gap-2">
          <button ref={goRef} onClick={onReview}
            className="fx-press w-full py-3 rounded-md text-base font-bold focus:outline-none focus:ring-2"
            style={{ background: C.accent, color: C.onAccent }}>Leave a review</button>
          <button onClick={onLater}
            className="fx-press w-full py-3 rounded-md text-base font-bold focus:outline-none focus:ring-2"
            style={{ background: "transparent", color: C.accent, border: `1px solid ${C.accent}` }}>Not now</button>
          <button onClick={onNever} className="text-sm underline mt-1 focus:outline-none focus:ring-2" style={{ color: C.muted }}>
            Don't ask again
          </button>
        </div>
      </div>
    </div>
  );
}
const reviewsOn = () => Boolean(APP_INFO.reviews && APP_INFO.reviews.formId && APP_INFO.reviews.rating);
const STAR_WORDS = ["", "Poor", "Fair", "Good", "Very good", "Excellent"];
function StarIcon({ filled }) {
  return (
    <svg width="36" height="36" viewBox="0 0 24 24" aria-hidden="true">
      <path d="M12 2.8l2.8 5.9 6.4.8-4.7 4.4 1.2 6.4L12 17.2l-5.7 3.1 1.2-6.4-4.7-4.4 6.4-.8z"
        style={{ fill: filled ? "#E8A317" : "none", stroke: filled ? "#B7791F" : C.muted, strokeWidth: 1.6, strokeLinejoin: "round" }} />
    </svg>
  );
}
function ReviewDialog({ onClose }) {
  const closeRef = useRef(null);
  const [stars, setStars] = useState(0);
  const [comment, setComment] = useState("");
  const [state, setState] = useState("form"); // form, sending, sent, error
  useEffect(() => {
    if (closeRef.current) closeRef.current.focus();
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);
  const send = async () => {
    const text = comment.trim().slice(0, 1000);
    if (!reviewsOn()) {
      const body = `Rating: ${stars} out of 5 stars\n\nComment: ${text || "(none)"}\n\n(${APP_INFO.name} ${APP_INFO.version})`;
      window.location.href = `mailto:${APP_INFO.contactEmail}?subject=${encodeURIComponent(`${APP_INFO.name} review: ${stars} stars`)}&body=${encodeURIComponent(body)}`;
      setState("sent");
      return;
    }
    setState("sending");
    const r = APP_INFO.reviews;
    const form = new URLSearchParams();
    form.set(`entry.${r.rating}`, String(stars));
    if (r.comment && text) form.set(`entry.${r.comment}`, text);
    if (r.version) form.set(`entry.${r.version}`, APP_INFO.version);
    try {
      // Google Forms doesn't send a readable reply to other websites, so a completed request counts as sent.
      await fetch(`https://docs.google.com/forms/d/e/${encodeURIComponent(r.formId)}/formResponse`,
        { method: "POST", mode: "no-cors", body: form });
      try { window.localStorage.setItem(REVIEW_KEY, new Date().toISOString()); } catch (e) { /* not critical */ }
      setState("sent");
    } catch (e) {
      setState("error");
    }
  };
  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-4" style={{ background: C.scrim }} onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-labelledby="review-title" className="fx-fade w-full max-w-md rounded-lg p-5 overflow-y-auto"
        style={{ background: C.surface, color: C.ink, maxHeight: "calc(100vh - 32px)", marginBottom: "env(safe-area-inset-bottom)" }}
        onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-2">
          <h2 id="review-title" className="text-xl font-bold">Rate {APP_INFO.name}</h2>
          <button ref={closeRef} onClick={onClose} aria-label="Close"
            className="fx-press flex items-center justify-center rounded-md text-2xl leading-none focus:outline-none focus:ring-2"
            style={{ width: 40, height: 40, color: C.muted, flexShrink: 0 }}>×</button>
        </div>
        {state === "sent" ? (
          <div className="fx-fade">
            <p className="text-lg font-bold mb-2">Thank you!</p>
            <p className="text-base mb-4">
              {reviewsOn() ? "Your review was sent. It helps us make the app better for everyone."
                : "Your email app should open with your review filled in. Tap send there to finish."}
            </p>
            <Button onClick={onClose}>Done</Button>
          </div>
        ) : (
          <>
            <p className="text-base mb-3">How would you rate the app?</p>
            <div role="radiogroup" aria-label="Star rating" className="flex items-center gap-1 mb-1">
              {[1, 2, 3, 4, 5].map((n) => (
                <button key={n} role="radio" aria-checked={stars === n} aria-label={`${n} ${n === 1 ? "star" : "stars"}`}
                  onClick={() => setStars(n)}
                  className="fx-press rounded-md focus:outline-none focus:ring-2" style={{ padding: 2, minWidth: 44, minHeight: 44 }}>
                  <StarIcon filled={n <= stars} />
                </button>
              ))}
            </div>
            <p className="text-sm mb-4" style={{ color: C.muted, minHeight: 20 }} aria-live="polite">
              {stars ? `${stars} out of 5: ${STAR_WORDS[stars]}` : "Tap a star"}
            </p>
            <Field label="Comments (optional)">
              <textarea rows={4} maxLength={1000} className={inputCls} style={{ ...inputStyle, fontFamily: "inherit" }}
                placeholder="What do you like? What could be better?" value={comment} onChange={(e) => setComment(e.target.value)} />
            </Field>
            <p className="text-sm mb-4 p-2 rounded-md" style={{ background: C.subtle, border: `1px solid ${C.line}` }}>
              Please don't include health or personal information. Reviews are anonymous: no name or email is sent.
              {reviewsOn() ? " They go to the developers through Google Forms." : ""}
            </p>
            {state === "error" && (
              <p className="text-sm mb-2" role="alert" style={{ color: C.error }}>
                The review couldn't be sent. Check your internet connection and try again.
              </p>
            )}
            <div className="flex flex-wrap gap-2">
              <Button onClick={send} disabled={!stars || state === "sending"}>{state === "sending" ? "Sending…" : "Send review"}</Button>
              <Button kind="secondary" onClick={onClose}>Cancel</Button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

